private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        if (!bb.hasRemaining()) {
            return i;
        }
        int b0 = bb.get() & 0xFF;
        int codePoint;
        if ((b0 & 0x80) == 0) {
            // 1-byte sequence
            codePoint = b0;
        } else if ((b0 & 0xE0) == 0xC0) {
            // 2-byte sequence
            if (bb.remaining() < 1) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b1 = bb.get() & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        } else if ((b0 & 0xF0) == 0xE0) {
            // 3-byte sequence
            if (bb.remaining() < 2) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        } else if ((b0 & 0xF8) == 0xF0) {
            // 4-byte sequence
            if (bb.remaining() < 3) {
                throw new IllegalArgumentException("Incomplete UTF-8 sequence");
            }
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 continuation byte");
            }
            codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 leading byte");
        }

        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            // Encode as surrogate pair
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        }
        return i + 1;
    } catch (java.nio.BufferUnderflowException e) {
        throw new IllegalArgumentException("Unexpected end of byte buffer while decoding UTF-8", e);
    }
}

private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    try {
        int newCapacity = this.capacity + size;
        if (newCapacity < 0) { // handle integer overflow
            newCapacity = Integer.MAX_VALUE;
        }
        byte[] newData = new byte[newCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.size);
        this.data = newData;
        this.capacity = newCapacity;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
}

