            }
        }
    }
}

public String format(LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    // Default conversion pattern: date, thread, level, logger, message, newline
    String pattern = "%d [%t] %-5p %c - %m%n";
    try {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            if (c == '%' && i + 1 < pattern.length()) {
                char next = pattern.charAt(i + 1);
                switch (next) {
                    case 'd':
                        // Format the event timestamp
                        long timeMillis = event.getTimeMillis();
                        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
                        sb.append(sdf.format(new java.util.Date(timeMillis)));
                        break;
                    case 't':
                        // Thread name
                        String threadName = null;
                        try {
                            threadName = event.getThreadName();
                        } catch (NoSuchMethodError e) {
                            // Fallback if method not available
                        }
                        sb.append(threadName != null ? threadName : Thread.currentThread().getName());
                        break;
                    case 'p':
                        // Log level
                        String level = null;
                        try {
                            level = event.getLevel() != null ? event.getLevel().toString() : null;
                        } catch (NoSuchMethodError e) {
                            // Fallback if method not available
                        }
                        sb.append(level != null ? level : "UNKNOWN");
                        break;
                    case 'c':
                        // Logger name
                        String loggerName = null;
                        try {
                            loggerName = event.getLoggerName();
                        } catch (NoSuchMethodError e) {
                            // Fallback if method not available
                        }
                        sb.append(loggerName != null ? loggerName : "UNKNOWN");
                        break;
                    case 'm':
                        // Message
                        String msg = null;
                        try {
                            msg = event.getMessage() != null ? event.getMessage().toString() : null;
                        } catch (NoSuchMethodError e) {
                            // Fallback if method not available
                        }
                        sb.append(msg != null ? msg : "");
                        break;
                    case 'n':
                        sb.append(System.lineSeparator());
                        break;
                    default:
                        sb.append('%').append(next);
                }
                i++; // Skip the conversion character
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    } catch (Exception e) {
        // Fallback: return the raw message if formatting fails
        try {
            return event.getMessage() != null ? event.getMessage().toString() : "";
        } catch (Exception ex) {
            return "";
        }
    }
}

