private int parseEndOfLine(String headerPart, int end) {
    // Validate input
    if (headerPart == null) {
        return -1;
    }
    // The next byte to examine is after the last processed byte
    int start = end + 1;
    if (start < 0 || start > headerPart.length()) {
        return -1;
    }
    // Search for the CRLF sequence
    int idx = headerPart.indexOf("\r\n", start);
    return idx; // returns -1 if not found
}

