public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    if (file.isDirectory()) {
        File[] children;
        try {
            children = file.listFiles();
        } catch (SecurityException se) {
            throw new IOException("Security exception while listing directory: " + file, se);
        }
        if (children == null) {
            throw new IOException("Failed to list contents of directory: " + file);
        }
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }
    try {
        if (!file.deleteOnExit()) {
            throw new IOException("Failed to schedule deletion of file: " + file);
        }
    } catch (SecurityException se) {
        throw new IOException("Security exception while scheduling deletion of file: " + file, se);
    }
}

