int addType(final String value) {
    // Validate input
    if (value == null) {
        throw new IllegalArgumentException("Type value cannot be null");
    }

    // Ensure the type table is initialized
    if (typeTable == null) {
        throw new IllegalStateException("Type table has not been initialized");
    }

    try {
        // Search for an existing type with the same value
        for (int i = 0; i < typeTable.size(); i++) {
            TypeSymbol ts = typeTable.get(i);
            // Assuming TypeSymbol has a method getName() that returns the internal class name
            if (value.equals(ts.getName())) {
                return i; // Return the index of the existing type
            }
        }

        // If not found, create a new TypeSymbol and add it to the table
        TypeSymbol newType = new TypeSymbol(value);
        typeTable.add(newType);
        return typeTable.size() - 1; // Return the index of the newly added type
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context
        throw new RuntimeException("Failed to add type: " + value, e);
    }
}

@Override public void accept(final METRICS data){
    if (data == null) {
        throw new IllegalArgumentException("data cannot be null");
    }
    try {
        // Ensure cache is initialized
        if (cache == null) {
            cache = new java.util.HashMap<>();
        }
        // Determine a key for the data
        Object key;
        try {
            java.lang.reflect.Method getKey = data.getClass().getMethod("getKey");
            key = getKey.invoke(data);
        } catch (NoSuchMethodException e) {
            // Fallback to using the data's toString() as a key
            key = data.toString();
        }
        METRICS existing = cache.get(key);
        if (existing != null) {
            try {
                java.lang.reflect.Method merge = existing.getClass().getMethod("merge", existing.getClass());
                merge.invoke(existing, data);
            } catch (NoSuchMethodException e) {
                // If no merge method, replace the existing entry
                cache.put(key, data);
            }
        } else {
            cache.put(key, data);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to accept data", e);
    }
}

void insertBefore(Bucket bucket) {
    // Validate input
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    // If this is already immediately before the target bucket, nothing to do
    if (this.next == bucket) {
        return;
    }

    // If this is immediately after the target bucket, we need to move it before
    // but we will handle it in the general case below.

    // Keep a reference to the original predecessor of the target bucket
    Bucket originalPrev = bucket.prev;

    // Detach this bucket from its current position if it is part of a list
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    // Insert this bucket before the target bucket
    this.next = bucket;
    this.prev = originalPrev;

    if (originalPrev != null) {
        originalPrev.next = this;
    }
    bucket.prev = this;
}

