public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("tableName must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings must not be null");
    }
    try {
        // Retrieve the current mapping for the given table (index)
        Mappings current = MappingUtils.getCurrentMapping(tableName);
        if (current == null) {
            return new Mappings();
        }

        java.util.Map<String, Object> currentProps = current.getProperties();
        java.util.Map<String, Object> historyProps = mappings.getProperties();
        java.util.Map<String, Object> diffProps = new java.util.HashMap<>();

        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String key = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(key)) {
                continue;
            }
            if (!historyProps.containsKey(key)) {
                diffProps.put(key, entry.getValue());
            }
        }

        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // Log the exception if a logger is available; otherwise swallow and return empty mapping
        return new Mappings();
    }
}

public void addNewTarget(Channels channels, IConsumer consumer) {
    if (channels == null) {
        throw new IllegalArgumentException("channels cannot be null");
    }
    if (consumer == null) {
        throw new IllegalArgumentException("consumer cannot be null");
    }
    try {
        java.lang.reflect.Method method = null;
        // Try common method names that might exist on Channels
        try {
            method = channels.getClass().getMethod("addTarget", IConsumer.class);
        } catch (NoSuchMethodException e) {
            try {
                method = channels.getClass().getMethod("add", IConsumer.class);
            } catch (NoSuchMethodException ex) {
                try {
                    method = channels.getClass().getMethod("addChannel", IConsumer.class);
                } catch (NoSuchMethodException exc) {
                    // If Channels implements java.util.Collection, try to add via Collection interface
                    if (channels instanceof java.util.Collection) {
                        java.util.Collection<?> col = (java.util.Collection<?>) channels;
                        col.add(consumer);
                        return;
                    }
                    throw new UnsupportedOperationException(
                        "No suitable method found to add consumer to Channels");
                }
            }
        }
        method.invoke(channels, consumer);
    } catch (IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
        throw new RuntimeException("Failed to add new target to Channels", e);
    }
}

public static void createConfigurationDirectory() {
