    }
}

public long readLong(final int offset){
    // Validate offset to ensure we can read 8 bytes
    if (offset < 0 || offset + 8 > bytes.length) {
        throw new IllegalArgumentException("Invalid offset for reading long: " + offset);
    }
    // Read 8 bytes in big-endian order and assemble into a signed long
    return ((long)(bytes[offset]     & 0xFF) << 56) |
           ((long)(bytes[offset + 1] & 0xFF) << 48) |
           ((long)(bytes[offset + 2] & 0xFF) << 40) |
           ((long)(bytes[offset + 3] & 0xFF) << 32) |
           ((long)(bytes[offset + 4] & 0xFF) << 24) |
           ((long)(bytes[offset + 5] & 0xFF) << 16) |
           ((long)(bytes[offset + 6] & 0xFF) << 8)  |
           ((long)(bytes[offset + 7] & 0xFF));
}

public boolean equals(final byte[] data, int offset, final int len) {
    // Validate input array
    if (data == null) {
        return false;
    }
    // Validate offset and length
    if (len < 0 || offset < 0) {
        return false;
    }
    // Prevent integer overflow when computing offset + len
    if ((long) offset + len > data.length) {
        return false;
    }
    // If internal array is null, only match if len is zero
    if (bytes == null) {
        return len == 0;
    }
    // Lengths must match
    if (bytes.length != len) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < len; i++) {
        if (bytes[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

