        Byte b = array[i];
        if (b == null) {
            throw new NullPointerException("array content is null at index " + i);
        }
        result[i] = b.byteValue();
    }
    return result;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    try{
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        long epochDay = date.toEpochDay();
        long bucketStartEpoch = (epochDay / dayStep) * dayStep;
        java.time.LocalDate bucketStartDate = java.time.LocalDate.ofEpochDay(bucketStartEpoch);
        return bucketStartDate.getYear() * 10000L + bucketStartDate.getMonthValue() * 100L + bucketStartDate.getDayOfMonth();
    }catch(java.time.DateTimeException e){
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket, e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0 || index > str.length() || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index: " + index + ", len: " + len + ", str.length(): " + str.length());
    }
    int end = index + len;
    int size = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                codePoint = Character.toCodePoint(ch, low);
                i += 2;
                // UTF-8 length for code points > 0xFFFF is 4 bytes
                size += 4;
                continue;
            }
        }
        // Not a surrogate pair
        codePoint = ch;
        i++;
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            // This case should not happen for a single char, but keep for completeness
            size += 4;
        }
    }
    return size;
}

