    }

    // Nullify this edge's own pointers to avoid dangling references
    prevTreeEdge = null;
    nextTreeEdge = null;
    prevTreeEdgeOpposite = null;
    nextTreeEdgeOpposite = null;
}

public static String findAndSubst(String key, Properties props) {
    try {
        if (key == null || props == null) {
            return null;
        }
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        String result = value;
        int maxDepth = 10;
        for (int depth = 0; depth < maxDepth; depth++) {
            java.util.regex.Matcher matcher = pattern.matcher(result);
            boolean found = false;
            java.lang.StringBuffer sb = new java.lang.StringBuffer();
            while (matcher.find()) {
                found = true;
                String varName = matcher.group(1);
                String varValue = props.getProperty(varName);
                if (varValue == null) {
                    varValue = matcher.group(0); // keep placeholder if not found
                }
                matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
            }
            matcher.appendTail(sb);
            result = sb.toString();
            if (!found) {
                break;
            }
        }
        return result;
    } catch (Exception e) {
        return null;
    }
}

