private static boolean isParameterSeparator(final char c) {
    // Treat null character and ISO control characters as separators
    if (c == '\0' || Character.isISOControl(c)) {
        return true;
    }
    // Whitespace characters are separators
    if (Character.isWhitespace(c)) {
        return true;
    }
    // Underscore is allowed in parameter names
    if (c == '_') {
        return false;
    }
    // Letters and digits are part of parameter names
    if (Character.isLetterOrDigit(c)) {
        return false;
    }
    // All other characters are considered separators
    return true;
}

