    }
    if (suffix.isEmpty()) {
        return true;
    }
    if (str.length() < suffix.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return new ArrayList<>();
    }
    // Remove leading '/' if present (absolute path)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] parts = rawPath.split("/");
    List<PathSegmentImpl> segments = new ArrayList<>(parts.length);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue; // ignore empty segments
        }
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the original part
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

