public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    if (minX > maxX) {
        throw new IllegalArgumentException("box minX is greater than maxX");
    }
    double midX = (minX + maxX) / 2.0;
    Box2D left = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive");
    }
    try {
        if (bytes == null) {
            bytes = new byte[size];
            return;
        }
        int oldCapacity = bytes.length;
        long newCapacityLong = (long) oldCapacity + size;
        if (newCapacityLong > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("Requested size too large");
        }
        int newCapacity = (int) newCapacityLong;
        byte[] newBytes = new byte[newCapacity];
        System.arraycopy(bytes, 0, newBytes, 0, oldCapacity);
        bytes = newBytes;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Failed to enlarge byte vector due to insufficient memory", e);
    }
}

