public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are both uppercase, leave unchanged
    if (len >= 2 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    return upperFirst + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int len = current.pos;
        if (len > 0 && current.buf != null) {
            // Ensure we don't exceed the buffer length
            int writeLen = Math.min(len, current.buf.length);
            out.write(current.buf, 0, writeLen);
            total += writeLen;
        }
        current = current.next;
    }
    return total;
}

