    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();

        // Timestamp
        try {
            java.lang.reflect.Method tsMethod = event.getClass().getMethod("getTimeStamp");
            Object tsObj = tsMethod.invoke(event);
            if (tsObj instanceof java.lang.Number) {
                long ts = ((java.lang.Number) tsObj).longValue();
                if (ts > 0) {
                    sb.append("[")
                      .append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                              .format(new java.util.Date(ts)))
                      .append("] ");
                }
            }
        } catch (Exception ignored) {}

        // Thread name
        try {
            java.lang.reflect.Method threadMethod = event.getClass().getMethod("getThreadName");
            Object threadObj = threadMethod.invoke(event);
            if (threadObj instanceof String) {
                sb.append("[")
                  .append(threadObj)
                  .append("] ");
            }
        } catch (Exception ignored) {}

        // Level
        try {
            java.lang.reflect.Method levelMethod = event.getClass().getMethod("getLevel");
            Object levelObj = levelMethod.invoke(event);
            if (levelObj != null) {
                sb.append("[")
                  .append(levelObj.toString())
                  .append("] ");
            }
        } catch (Exception ignored) {}

        // Logger name
        try {
            java.lang.reflect.Method loggerMethod = event.getClass().getMethod("getLoggerName");
            Object loggerObj = loggerMethod.invoke(event);
            if (loggerObj instanceof String) {
                sb.append(loggerObj).append(" - ");
            }
        } catch (Exception ignored) {}

        // Message
        try {
            java.lang.reflect.Method msgMethod = event.getClass().getMethod("getMessage");
            Object msgObj = msgMethod.invoke(event);
            if (msgObj != null) {
                sb.append(msgObj.toString());
            } else {
                sb.append(event.toString());
            }
        } catch (Exception ignored) {
            sb.append(event.toString());
        }

        // Throwable information
        try {
            java.lang.reflect.Method throwableInfoMethod = event.getClass().getMethod("getThrowableInformation");
            Object throwableInfoObj = throwableInfoMethod.invoke(event);
            if (throwableInfoObj != null) {
                java.lang.reflect.Method getThrowableMethod = throwableInfoObj.getClass().getMethod("getThrowable");
                Object throwableObj = getThrowableMethod.invoke(throwableInfoObj);
                if (throwableObj instanceof java.lang.Throwable) {
                    sb.append(System.lineSeparator()).append(((java.lang.Throwable) throwableObj).toString());
                }
            }
        } catch (Exception ignored) {}

        return sb.toString();
    } catch (Exception e) {
        // Fallback to event's toString if anything goes wrong
        return event.toString();
    }
}

