private void putAbstractTypes(final int start, final int end) {
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices");
    }
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        stackMapTableEntries[stackMapTableEntriesOffset++] = (byte) type;
        if (type == 7) { // ITEM_Object
            int classIndex = currentFrame[i + 1];
            stackMapTableEntries[stackMapTableEntriesOffset++] = (byte) (classIndex >> 8);
            stackMapTableEntries[stackMapTableEntriesOffset++] = (byte) classIndex;
            i++;
        } else if (type == 8) { // ITEM_Uninitialized
            int offset = currentFrame[i + 1];
            stackMapTableEntries[stackMapTableEntriesOffset++] = (byte) (offset >> 8);
            stackMapTableEntries[stackMapTableEntriesOffset++] = (byte) offset;
            i++;
        }
    }
}

