    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof CharSequence) {
        String s = value.toString();
        if (s.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        return s.charAt(0);
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

