public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // Count consecutive backslashes
        int j = i;
        while (j < len && str.charAt(j) == '\\') {
            j++;
        }
        int backslashCount = j - i;
        if (backslashCount % 2 == 0) {
            // Even number of backslashes: all are literal
            sb.append("\\", 0, backslashCount / 2);
            i = j;
            continue;
        }
        // Odd number: (backslashCount-1)/2 literal backslashes, last escapes next char
        sb.append("\\", 0, (backslashCount - 1) / 2);
        i = j; // position of the escape character
        if (i >= len) {
            // Trailing backslash, treat as literal
            sb.append('\\');
            break;
        }
        char esc = str.charAt(i);
        switch (esc) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 4 >= len) {
                    throw new Exception("Incomplete Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                }
                i += 4; // skip the 4 hex digits
                break;
            default:
                // Octal escape: up to 3 octal digits (0-7)
                if (esc >= '0' && esc <= '7') {
                    int octal = esc - '0';
                    int k = 1;
                    while (k < 3 && i + k < len) {
                        char d = str.charAt(i + k);
                        if (d >= '0' && d <= '7') {
                            octal = (octal << 3) + (d - '0');
                            k++;
                        } else {
                            break;
                        }
                    }
                    sb.append((char) octal);
                    i += k - 1; // adjust for extra increments
                } else {
                    // Unrecognized escape, keep as is
                    sb.append(esc);
                }
                break;
        }
        i++;
    }
    return sb.toString();
}

