protected int removeUnusedNodes() {
    int removedCount = 0;
    // If this node has no children, nothing to remove
    if (this.children == null) {
        return 0;
    }
    java.util.Iterator<Category> it = this.children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        try {
            if (!child.isActive()) {
                // Remove inactive child
                it.remove();
                removedCount++;
            } else {
                // Recursively remove from child
                removedCount += child.removeUnusedNodes();
            }
        } catch (Exception e) {
            // Exception handling: ignore or log as needed
        }
    }
    return removedCount;
}

