final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate classFileBuffer
    if (classFileBuffer == null) {
        throw new IllegalArgumentException("classFileBuffer is null");
    }
    // Validate constant pool count
    if (classFileBuffer.length < 10) {
        throw new IllegalArgumentException("classFileBuffer too short to contain header");
    }
    final int constantPoolCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds: " + constantPoolEntryIndex);
    }
    // Find the offset of the desired constant pool entry
    int offset = 10; // start of constant pool
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        if (offset >= classFileBuffer.length) {
            throw new IllegalArgumentException("classFileBuffer truncated while scanning constant pool");
        }
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                if (offset + 1 >= classFileBuffer.length) {
                    throw new IllegalArgumentException("classFileBuffer truncated while reading Utf8 length");
                }
                int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + length;
                break;
            }
            case 3: case 4: // Integer, Float
                offset += 4;
                break;
            case 5: case 6: // Long, Double
                offset += 8;
                i++; // these take up two entries
                break;
            case 7: case 8: // Class, String
                offset += 2;
                break;
            case 9: case 10: case 11: // Fieldref, Methodref, InterfaceMethodref
                offset += 4;
                break;
            case 12: // NameAndType
                offset += 4;
                break;
            case 15: // MethodHandle
                offset += 3;
                break;
            case 16: // MethodType
                offset += 2;
                break;
            case 18: // InvokeDynamic
                offset += 4;
                break;
            case 19: case 20: // Module, Package
                offset += 2;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    // Now offset points to the tag of the desired entry
    if (offset >= classFileBuffer.length) {
        throw new IllegalArgumentException("classFileBuffer truncated before desired entry");
    }
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Requested constant pool entry is not a CONSTANT_Utf8 (tag=" + tag + ")");
    }
    offset++; // move past tag
    if (offset + 1 >= classFileBuffer.length) {
        throw new IllegalArgumentException("classFileBuffer truncated while reading Utf8 length");
    }
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Provided charBuffer too small for Utf8 string (required " + length + ", available " + charBuffer.length + ")");
    }
    if (offset + length > classFileBuffer.length) {
        throw new IllegalArgumentException("classFileBuffer truncated while reading Utf8 bytes");
    }
    // Decode bytes into charBuffer using UTF-8
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, offset, length);
    java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer, 0, length);
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    decoder.onMalformedInput(java.nio.charset.CodingErrorAction.REPORT);
    decoder.onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT);
    try {
        decoder.decode(byteBuf, charBuf, true);
        decoder.flush(charBuf);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new IllegalArgumentException("Failed to decode UTF-8 string from constant pool", e);
    }
    charBuf.flip();
    return new String(charBuffer, 0, charBuf.limit());
}

private static char decodeHexNibble(final char c){
    if (c >= '0' && c <= '9') {
        return (char)(c - '0');
    }
    if (c >= 'a' && c <= 'f') {
        return (char)(c - 'a' + 10);
