        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }
    if (byteArrayValue == null) {
        // Ensure capacity for nullbytes
        if (size + byteLength > data.length) {
            int newCap = Math.max(data.length * 2, size + byteLength);
            data = java.util.Arrays.copyOf(data, newCap);
        }
        for (int i = size; i < size + byteLength; i++) {
            data[i] = 0;
        }
        size += byteLength;
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds");
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
    }
    if (size + byteLength > data.length) {
        int newCap = Math.max(data.length * 2, size + byteLength);
        data = java.util.Arrays.copyOf(data, newCap);
    }
    System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    size += byteLength;
    return this;
