    if (bean == null) {
        return java.util.Collections.emptyList();
    }
    try {
        java.beans.BeanInfo beanInfo = java.beans.Introspector.getBeanInfo(bean.getClass(), Object.class);
        java.beans.PropertyDescriptor[] pds = beanInfo.getPropertyDescriptors();
        java.util.List<Object> values = new java.util.ArrayList<>(pds.length);
        for (java.beans.PropertyDescriptor pd : pds) {
            java.lang.reflect.Method readMethod = pd.getReadMethod();
            if (readMethod != null) {
                Object value = readMethod.invoke(bean);
                values.add(value);
            }
        }
        return java.util.Collections.unmodifiableCollection(values);
    } catch (java.beans.IntrospectionException | java.lang.reflect.InvocationTargetException | java.lang.IllegalAccessException e) {
        throw new RuntimeException("Failed to retrieve bean values", e);
    }
}

