public final MatchResult match(CharSequence uri) {
    // Return null for null input or if the pattern is not initialized
    if (uri == null || pattern == null) {
        return null;
    }
    try {
        Matcher matcher = pattern.matcher(uri);
        if (matcher.matches()) {
            // Return a MatchResult representing the successful match
            return matcher.toMatchResult();
        }
        // No match found
        return null;
    } catch (Exception e) {
        // In case of any runtime exception (e.g., pattern mismatch, illegal state),
        // return null to indicate no match rather than propagating the exception.
        return null;
    }
}

public static byte convertHexDigit(byte b){
    if (b >= '0' && b <= '9') {
        return (byte)(b - '0');
    } else if (b >= 'a' && b <= 'f') {
        return (byte)(b - 'a' + 10);
    } else if (b >= 'A' && b <= 'F') {
        return (byte)(b - 'A' + 10);
    } else {
        throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
    }
}

