private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalArgumentException("modelName cannot be null or empty");
    }
    try {
        java.util.List<Integer> indices = getShardingKeyIndices(modelName);
        if (indices == null || indices.isEmpty()) {
            return;
        }
        java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
        java.util.Collections.sort(sorted);
        for (int i = 1; i < sorted.size(); i++) {
            if (sorted.get(i) - sorted.get(i - 1) != 1) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to check sharding key indices for model: " + modelName, e);
    }
}

public byte readByte() throws IOException {
    try {
        // Ensure the buffer is initialized and has data
        if (buffer == null || buffer.length == 0) {
            buffer = new byte[8192]; // default buffer size
        }
        if (pos >= limit) {
            if (in == null) {
                throw new IOException("Input stream is null");
            }
            int bytesRead = in.read(buffer, 0, buffer.length);
            if (bytesRead <= 0) {
                throw new IOException("No more data available");
            }
            pos = 0;
            limit = bytesRead;
        }
        return buffer[pos++];
    } catch (IOException e) {
        throw e; // propagate IOExceptions unchanged
    } catch (Exception e) {
        // Wrap any unexpected runtime exception in an IOException
        throw new IOException("Unexpected error while reading byte", e);
    }
}

