public double vertexWeight(Set<V> v) {
    if (v == null || v.isEmpty()) {
        return 0.0;
    }
    double sum = 0.0;
    try {
        if (edges != null) {
            for (Edge<V> e : edges) {
                if (e == null) {
                    continue;
                }
                V target = e.getTarget();
                if (target != null && v.contains(target)) {
                    sum += e.getWeight();
                }
            }
        }
    } catch (Exception ex) {
        // In case of any unexpected exception, return the sum computed so far
    }
    return sum;
}

public int compare(Object aObj1, Object aObj2) {
    // Handle reference equality first
    if (aObj1 == aObj2) {
        return 0;
    }
    // Null handling: null is considered less than any non‑null value
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Both objects must implement Comparable to be compared
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            // The objects are not mutually comparable
            throw new ClassCastException("Objects are not mutually comparable: " + aObj1.getClass() + " vs " + aObj2.getClass());
        }
    }
    // If we reach here, the objects cannot be compared
    throw new ClassCastException("Objects are not comparable: " + aObj1.getClass() + " vs " + aObj2.getClass());
}

