        // In case of any unexpected error, return an empty array
        return new byte[0];
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour set and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new org.jgrapht.graph.DefaultGraphPath<>(graph, new java.util.ArrayList<>(), new java.util.ArrayList<>(), 0.0);
    }
    // Build adjacency map
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the graph");
        }
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new java.util.ArrayList<>()).add(e);
    }
    // Determine start vertex (prefer vertex with degree 1)
    V start = null;
    for (java.util.Map.Entry<V, java.util.List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // No endpoint found, pick arbitrary vertex
        start = adjacency.keySet().iterator().next();
    }
    boolean directed = graph.getType().isDirected();
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    java.util.Set<E> visited = new java.util.HashSet<>();
    V current = start;
    vertexList.add(current);
    while (visited.size() < tour.size()) {
        E nextEdge = null;
        V nextVertex = null;
        java.util.List<E> edges = adjacency.get(current);
        if (edges == null) {
            break;
        }
        for (E e : edges) {
            if (visited.contains(e)) {
                continue;
            }
            if (directed) {
                if (graph.getEdgeSource(e).equals(current)) {
                    nextEdge = e;
                    nextVertex = graph.getEdgeTarget(e);
                    break;
                }
            } else {
                if (graph.getEdgeSource(e).equals(current)) {
                    nextEdge = e;
                    nextVertex = graph.getEdgeTarget(e);
                    break;
                } else if (graph.getEdgeTarget(e).equals(current)) {
                    nextEdge = e;
                    nextVertex = graph.getEdgeSource(e);
                    break;
                }
            }
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        visited.add(nextEdge);
        current = nextVertex;
        vertexList.add(current);
    }
    if (visited.size() != tour.size()) {
        throw new IllegalArgumentException("Cannot construct a tour from the given edge set");
    }
    double weight = 0.0;
    for (E e : tour) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

