int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    if (constantPool == null) {
        throw new IllegalStateException("Constant pool is not initialized");
    }
    // Ensure the name and descriptor UTF-8 entries exist and get their indices
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);
    // Check if a matching CONSTANT_NameAndType_info already exists
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPoolInfo info = constantPool.get(i);
        if (info instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nt = (ConstantNameAndTypeInfo) info;
            if (nt.getNameIndex() == nameIndex && nt.getDescriptorIndex() == descriptorIndex) {
                return i;
            }
        }
    }
    // Add the new CONSTANT_NameAndType_info to the pool
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(newEntry);
    return constantPool.size() - 1;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new IllegalArgumentException("Trailing backslash in input");
            }
            char next = input.charAt(++i);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case 'a':
                    sb.append('\u0007'); // bell
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case 'x':
                    if (i + 2 >= len) {
                        throw new IllegalArgumentException("Incomplete \\x escape sequence");
                    }
                    String hex2 = input.substring(i + 1, i + 3);
                    try {
                        int val = Integer.parseInt(hex2, 16);
                        sb.append((char) val);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex in \\x escape: " + hex2, e);
                    }
                    i += 2;
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new IllegalArgumentException("Incomplete \\u escape sequence");
                    }
                    String hex4 = input.substring(i + 1, i + 5);
                    try {
                        int val = Integer.parseInt(hex4, 16);
                        sb.append((char) val);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex in \\u escape: " + hex4, e);
                    }
                    i += 4;
                    break;
                case 'U':
                    if (i + 8 >= len) {
                        throw new IllegalArgumentException("Incomplete \\U escape sequence");
                    }
                    String hex8 = input.substring(i + 1, i + 9);
                    try {
                        long valLong = Long.parseLong(hex8, 16);
                        if (valLong > 0x10FFFF) {
                            throw new IllegalArgumentException("Code point out of range in \\U escape: " + hex8);
                        }
                        int val = (int) valLong;
                        sb.append(Character.toChars(val));
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex in \\U escape: " + hex8, e);
                    }
                    i += 8;
                    break;
                default:
                    sb.append(next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one of the arrays is null, return a copy of the other
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }
    // Both arrays are non-null; create a new array to hold all elements
    int len1 = array1.length;
    int len2 = array2.length;
    String[] result = new String[len1 + len2];
    // Copy elements from the first array
    System.arraycopy(array1, 0, result, 0, len1);
    // Copy elements from the second array
    System.arraycopy(array2, 0, result, len1, len2);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer v : new java.util.HashSet<>(source)) {
        if (v == null) {
            continue;
        }
        if (v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException("vertex id out of bounds: " + v);
        }
        target.add(v);
        labels.set(v, 0);
    }
    source.clear();
}

