private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // Verify that the node is actually part of this list.
    // If the node has no neighbours, it could be the sole element.
    if (node.prev == null && node.next == null) {
        if (node != head && node != tail) {
            return false; // node is not in the list
        }
    } else {
        // If node.prev is null but node is not the head, it's not in the list.
        if (node.prev == null && node != head) {
            return false;
        }
        // If node.next is null but node is not the tail, it's not in the list.
        if (node.next == null && node != tail) {
            return false;
        }
    }

    // Unlink the node from its neighbours.
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // node is the head
        head = node.next;
    }

    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node is the tail
        tail = node.prev;
    }

    // Clean up the node's own references.
    node.prev = null;
    node.next = null;

    // Update the list size.
    size--;

    return true;
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new ArrayList<>();
    try {
        if (currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) continue;
            List<Segment> segments = profile.getSegments();
            if (segments == null) continue;
            for (Segment segment : segments) {
                if (segment == null) continue;
                List<Snapshot> snapshots = segment.getSnapshots();
                if (snapshots == null) continue;
                for (Snapshot snapshot : snapshots) {
                    if (snapshot == null) continue;
                    List<SearchSequence> sequences = snapshot.getSearchSequences();
                    if (sequences == null) continue;
                    for (SearchSequence seq : sequences) {
                        if (seq == null) continue;
                        int start = seq.getStart();
                        int end = seq.getEnd();
