private String parseToken(final char[] terminators) {
    // If the source string is null, return an empty token
    if (input == null) {
        return "";
    }
    int length = input.length();
    // If the current position is already at or beyond the end, nothing to parse
    if (pos >= length) {
        return "";
    }
    StringBuilder token = new StringBuilder();
    while (pos < length) {
        char current = input.charAt(pos);
        boolean isTerminator = false;
        if (terminators != null) {
            for (char t : terminators) {
                if (current == t) {
                    isTerminator = true;
                    break;
                }
            }
        }
        if (isTerminator) {
            // Stop before consuming the terminator
            break;
        }
        token.append(current);
        pos++;
    }
    return token.toString();
}

