public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (this.name == null) {
        throw new IllegalStateException("name is null");
    }
    if (nameStart < 0 || nameStart >= this.name.length()) {
        throw new IndexOutOfBoundsException("nameStart out of bounds");
    }
    int i = nameStart;
    // Skip any leading whitespace
    while (i < this.name.length() && Character.isWhitespace(this.name.charAt(i))) {
        i++;
    }
    while (i < this.name.length()) {
        // Append the first character of the current word
        buf.append(this.name.charAt(i));
        // Move to the end of the current word
        i++;
        while (i < this.name.length() && !Character.isWhitespace(this.name.charAt(i))) {
            i++;
        }
        // Skip whitespace to the start of the next word
        while (i < this.name.length() && Character.isWhitespace(this.name.charAt(i))) {
            i++;
        }
    }
}

