private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // An empty set or a single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure no null vertices
    for (V v : vertices) {
        if (v == null) {
            throw new IllegalArgumentException("Vertices set must not contain null");
        }
    }
    // Check every unordered pair of distinct vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    int n = keys.size();
    for (int i = 0; i < n; i++) {
        K key = keys.get(i);
        if (key == null || !(key instanceof Comparable)) {
            lowerBounds.add(-1);
            continue;
        }
        Comparable<? super K> compKey = (Comparable<? super K>) key;
        int maxIndex = -1;
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            K other = keys.get(j);
            if (other == null || !(other instanceof Comparable)) continue;
            Comparable<? super K> compOther = (Comparable<? super K>) other;
            if (compKey.compareTo(other) > 0) {
                if (maxIndex == -1 || compOther.compareTo(keys.get(maxIndex)) > 0) {
                    maxIndex = j;
                }
            }
        }
        lowerBounds.add(maxIndex);
    }
    return lowerBounds;
}

