public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    // If relativePath is empty, return the original path unchanged
    if (relativePath.isEmpty()) {
        return path;
    }
    // If path is empty, treat the relative path as the result
    if (path.isEmpty()) {
        return relativePath;
    }

    // Determine if the original path is absolute (starts with '/')
    boolean leadingSlash = path.startsWith("/");

    // Use a list as a stack to hold path components
    java.util.List<String> stack = new java.util.ArrayList<>();

    // Process the base path components
    String[] baseParts = path.split("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // Skip empty or current directory references
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
            // If stack is empty and path is absolute, ignore leading '..'
            continue;
        }
        stack.add(part);
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // Skip empty or current directory references
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
            // If stack is empty and path is absolute, ignore leading '..'
            continue;
        }
        stack.add(part);
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If the result is empty but the original path was absolute, return root "/"
    if (result.length() == 0 && leadingSlash) {
        result.append("/");
    }

    return result.toString();
}

