public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            // Non-positive threshold means never expire
            return false;
        }
        long currentTime = System.currentTimeMillis();
        // If timestamp is in the future, treat as not expired
        if (timestamp > currentTime) {
            return false;
        }
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, conservatively return false
        return false;
    }
}

