protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    if (clientSockets == null) {
        return;
    }
    synchronized (clientSockets) {
        java.util.Iterator<java.net.Socket> it = clientSockets.iterator();
        while (it.hasNext()) {
            java.net.Socket socket = it.next();
            if (socket == null || socket.isClosed()) {
                it.remove();
                continue;
            }
            try {
                java.io.OutputStream out = socket.getOutputStream();
                out.write((message + System.lineSeparator()).getBytes(java.nio.charset.StandardCharsets.UTF_8));
                out.flush();
            } catch (java.io.IOException e) {
                it.remove();
                System.err.println("Failed to send log message to client: " + e.getMessage());
            } catch (Exception e) {
                System.err.println("Unexpected error sending log message: " + e);
            }
        }
    }
}

