    }
    // Ensure capacity for two more bytes
    int newLength = this.length + 2;
    if(newLength > this.data.length){
        int newCap = Math.max(newLength, this.data.length * 2);
        byte[] newData = new byte[newCap];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }
