    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty()) {
                continue;
            }
            try {
                // Assume ThreadSnapshot has a static parse method that returns a snapshot or null
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
                if (snapshot == null) {
                    continue;
                }
                if (timeRanges == null || timeRanges.isEmpty()) {
                    result.add(snapshot);
                } else {
                    long ts = snapshot.getTimestamp(); // Assume getter exists
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (range.contains(ts)) {
                            result.add(snapshot);
                            break;
                        }
                    }
                }
            } catch (Exception e) {
                // Skip malformed lines but continue processing
                // Optionally log the error if a logger is available
            }
        }
    }
    return result;
}
